    ["通用任务挂接交互空模型（开门-复制改交互名称）"] = "ƨƇǦƽƔǃƽǦǉǇốǃƼǦǉươǃƼǦǉƑƸǦƼắǃǦǃƽƾệǂǦǋụǦƸƽǊǃƼǦ(ƨởǦƸửƶǦ-ǦƮƶǄǦƸƽƗǅǦǇồƾǦđổƾǦǉƙǃǦǉươǃƼǦǉƑƸ)",
    ["【普】狗尾巴花"] = "[ƫƽổ]ƣǄƶǦđǊƇƾǦƸƽƚ",
    ["造成{}，若自身8秒内再次释放次技能强化此技能对敌方全体目标造成一次额外{}。"] = "ƢƁǓǦ{},ǦǃếǊǦƷảǃǦǉƽƁǃǦǉǇǄǃƼǦǋƛǃƼǦ8ǦƼƾƁǓǦƼƾảƾǦǅƽƚǃƼǦǁạƾǦǁầǃǦǃữƶ,ǦǀỹǦǃăǃƼǦǃƐǓǦǈẽǦƸườǃƼǦƽƚƶ,ǦƼƁǓǦǉƽƙǂǦ{}ǦƸƽǄǦǉǄƐǃǦƷộǦǂụƸǦǉƾƙǊǦđịƸƽ.",
    ["每有一个满级道具或武学自身总{}提高n%"] = "ƨỗƾǦǀƽƾǦƸƚǦǂộǉǦđạǄǦƸụǦƽǄặƸǦǋƅǦƽọƸǦđạǉǦƸấǅǦǉốƾǦđƶ,ǦǉổǃƼǦ{}ǦƸủƶǦƷảǃǦǉƽƁǃǦǉăǃƼǦǃ%",
    ["【普】无猫不起浪"] = "[ǥƽườǃƼ]ƦƽƇǃƼǦƸƚǦǂƘǄǦǀƽƇǃƼǦƸƚǦǈƚǃƼ",
    ["使用独侠猫参与一次对局"] = "ƮửǦǤụǃƼǦƨƘǄǦĐộƸǦƣƾệǅǦǉƽƶǂǦƼƾƶǦǂộǉǦǋƑǃǦđấǊ",
    ["宝箱指令：控制"] = "ƧệǃƽǦǇươǃƼǦƷƑǊ:ǦĐƾềǊǦǀƽƾểǃ",
    ["记录有皇宫各处风物，不知何人所写。  "] = "ƢƽƾǦƸƽƗǅǦǅƽǄǃƼǦǋậǉǦǀƽắǅǦǃơƾǦǉǇǄǃƼǦƽǄƐǃƼǦƸǊǃƼ,ǦǀƽƇǃƼǦƷƾếǉǦǁƐǦƶƾǦǋƾếǉ.",
    ["建隆三年\t岁次壬戌"] = "ƦƾếǃǦƧǄǃƼǦǃăǂǦǉƽứǦƷƶ\tǥǊếǦǉƽứǦƩƽƁǂǦǥǊấǉ",
    ["【良】猫扑箭"] = "[ƧươǃƼ]ƨƾƙǊǦƫƽƑƸǦǥƾễǃ",
