    ["【极】相见欢"] = "[ƞựƸ]ǦǥươǃƼǦƦƾếǃǦƣǄƶǃ",
    ["风雪岱山-马车（带马）-反向"] = "ƫƽǄǃƼǦǥǊǓếǉǦĐạƾǦƮơǃǦ-ǦƳƺǦǃƼựƶǦ(ƸƚǦǃƼựƶ)Ǧ-ǦƞƽƾềǊǦǃƼượƸ",
    ["10%吸血"] = "10%ǦƽƕǉǦǂƑǊ",
    ["按#Y【纵笔泼墨】#E可切换为#Y自由#E书写模式，可在地上自由书写，并更换不同笔触。\n该模式下，玩法积分获取速度增加#Y20%#E。老师获得讲堂学筹速度提升#Y100%#E"] = "ẤǃǦ#Y[ƫƽƚǃƼǦƝƕǉǦǥựǦǝǄ]#EǦƸƚǦǉƽểǦƸƽǊǓểǃǦǈƶǃƼǦƸƽếǦđộǦǋƾếǉǦ#YǉựǦǤǄ#E,ǦƸƚǦǉƽểǦǉựǦǤǄǦǋƾếǉǦǉǇƙǃǦǂặǉǦđấǉǦǋƐǦǉƽƶǓǦđổƾǦƸƑƸǦǃƗǉǦƷƕǉǦǀƽƑƸǦǃƽƶǊ.\nǥǇǄǃƼǦƸƽếǦđộǦǃƐǓ,ǦǉốƸǦđộǦǃƽậǃǦĐƾểǂǦǉƓƸƽǦǁũǓǦǉăǃƼǦǉƽƙǂǦ#Y20%#E.ǦǥốƸǦđộǦǃƽậǃǦƣọƸǦǥǇƖǦƢƾảǃƼǦĐườǃƼǦƸủƶǦƧƃǄǦǈưǦǉăǃƼǦǉƽƙǂǦ#Y100%#E",
    ["宠物拼食玩法未开始"] = "ƧốƾǦƸƽơƾǦǉƽƕǦƸưǃƼǦǉǇƶǃƽǦăǃǦƸƽưƶǦƷắǉǦđầǊ",
    ["[左侧技能造成伤害时]"] = "[ƦƽƾǦǀỹǦǃăǃƼǦƷƙǃǦǉǇƑƾǦƼƁǓǦǈƑǉǦǉƽươǃƼ]",
    ["{name}跳到高处休息，感到惬意"] = "{name}ǦǃƽảǓǦǁƙǃǦƸƽỗǦƸƶǄǦǃƼƽỉǦǃƼơƾ,ǦƸảǂǦǉƽấǓǦǤễǦƸƽịǊ",
    ["出售时获得中量金币，可以用于锻造"] = "ƦƽƾǦƷƑǃǦǃƽậǃǦđượƸǦǂộǉǦǁượǃƼǦǋƐǃƼǦǉǇǊǃƼǦƷƔǃƽ,ǦƸƚǦǉƽểǦǤƖǃƼǦđểǦǇƘǃ",
    ["宝箱给自身套盾，金币额外增加护盾量"] = "ƭươǃƼǦƷƑǊǦǉựǦǉạǄǦǀƽƾƙǃǦƸƽǄǦƷảǃǦǉƽƁǃ,ǦǋƐǃƼǦǉăǃƼǦǉƽƙǂǦǁượǃƼǦǀƽƾƙǃ",
    ["【极】神仙玉咪粉"] = "[ƞựƸ]ǥƽầǃǦǥƾƙǃǦƩƼọƸǦƨƾǦƫƽấǃ",
    ["【极】鹅！"] = "[ƞựƸ]ƩƼỗǃƼ!",
    ["【极】受击回血符"] = "[ƞựƸ]ƝƖƶǦƽồƾǦǂƑǊǦǀƽƾǦƷịǦđƑǃƽ",
    ["通缉令-贰"] = "ƧệǃƽǦǉǇǊǓǦǃƃ-ƣƶƾ",
    ["每受击x次使自身回复基于最大生命值的血量"] = "ƨỗƾǦǀƽƾǦƷịǦđƑǃƽǦǉǇƕǃƼǦǍǦǁầǃǦǈẽǦǀƽƾếǃǦƷảǃǦǉƽƁǃǦƽồƾǦǅƽụƸǦǁượǃƼǦǂƑǊǦǤựƶǦǉǇƙǃǦǂƑǊǦǉốƾǦđƶ",
    ["雷"] = "ƧƇƾ",
    ["风雪岱山-马车（不带马）-反向"] = "ƫƽǄǃƼǦǥǊǓếǉǦĐạƾǦƮơǃǦ-ǦƳƺǦǃƼựƶǦ(ǀƽƇǃƼǦƸƚǦǃƼựƶ)Ǧ-ǦƩƼượƸǦƸƽƾềǊ",
    ["伙伴吃饱喝足，默契值增加了！"] = "ǥƽƕǦƸưǃƼǦđƃǦăǃǦǃǄǦǊốǃƼǦđủ,ǦđộǦăǃǦƈǦđƃǦǉăǃƼ!",
    ["好孩子，去！\n嘶嘶！"] = "ƩƼǄƶǃǦǁắǂ,ǦđƾǦđƾ!\nƳƔǦǍƔ!",
    ["传言石吼尤其喜爱吃烧饼，上供过烧饼的学子总能在旬考中取得不错的成绩。\n膳房的烧饼很好吃，但为了能受到石吼的青睐，用其上供学子络绎不绝，以至于放烧饼的篮子总是满满当当。\n这些烧饼一到晚上就进了在习斋中勤学苦读之人的腹中。\n没有一个烧饼会被浪费。"] = "ǥǇǊǓềǃǦǃƼƇǃǦǥƽạƸƽǦƣốǃƼǦđặƸǦƷƾệǉǦǉƽƓƸƽǦăǃǦƷƑǃƽǦǃướǃƼ,ǦƽọƸǦǉửǦǉừǃƼǦƸƕǃƼǦǉếǦƷƑǃƽǦǃướǃƼǦǁǊƇǃǦƸƚǦǉƽểǦđạǉǦǉƽƐǃƽǦǉƓƸƽǦǉốǉǦǉǇǄǃƼǦǀỳǦǉƽƾǦǂườƾǦǃƼƐǓ.\nƝƑǃƽǦǃướǃƼǦƸủƶǦǃƽƐǦƷếǅǦǇấǉǦǃƼǄǃ,ǦǃƽưǃƼǦđểǦđượƸǦǥƽạƸƽǦƣốǃƼǦđǄƑƾǦƽǄƐƾ,ǦƽọƸǦǉửǦǤƖǃƼǦǃƚǦǁƐǂǦđồǦƸƕǃƼǦǁũǦǁượǉǦǀƗǄǦđếǃǦǀƽƇǃƼǦǃƼớǉ,ǦǀƽƾếǃǦƸƽǄǦƼƾỏǦđựǃƼǦƷƑǃƽǦǃướǃƼǦǁƕƸǦǃƐǄǦƸũǃƼǦđầǓǦắǅ.\nƩƽữǃƼǦƸƽƾếƸǦƷƑǃƽǦǃướǃƼǦǃƐǓǦƸứǦđếǃǦǉốƾǦǁƐǦƸƽǊƾǦǋƐǄǦƷụǃƼǦƸủƶǦǃƽữǃƼǦǃƼườƾǦđƶǃƼǦǈƾƙǃƼǦǃăǃƼǦƽọƸǦǉậǅǦǉǇǄǃƼǦǥậǅǦǥǇƶƾ.\nƦƽƇǃƼǦǂộǉǦƸƽƾếƸǦƷƑǃƽǦǃướǃƼǦǃƐǄǦƷịǦǁƃǃƼǦǅƽƓ.",
    ["【普】毒鹅箭"] = "[ƫƽổ]ǦĐộƸǦƩƼỗǃƼǦǥƾễǃ",
    ["【普】百宝袋"] = "[ƫƽổ]ǦǥƕƾǦƝƑƸƽǦƝảǄ",
    ["这个月，第一千声雷就要响了。孤云算过的，错不了。\n二曜不同天，遁隐西极。这些都知道了，那“三一“、”齐物”是指什么？魔头会知道吗？\n谁！\n高盛！高盛！"] = "ǥƽƑǃƼǦǃƐǓ,ǦǉƾếǃƼǦǈấǂǦǉƽứǦǂộǉǦǃƼƐǃǦǈắǅǦǈửƶǦǋƶǃƼǦǁƙǃǦǇồƾ.ǦƞƇǦƱƁǃǦđƃǦƷấǂǦǉǄƑǃǦǆǊƶ,ǦǀƽƇǃƼǦǈƶƾǦđượƸ.\nƩƽịǦǤƾệǊǦƷấǉǦđồǃƼǦǉƽƾƙǃ,ǦđộǃǦẩǃǦǉƁǓǦƸựƸ.ǦƩƽữǃƼǦđƾềǊǦǃƐǓǦđềǊǦđƃǦƷƾếǉ,ǦǋậǓǦ\"ǥƶǂǦƩƽấǉ\",Ǧ\"ǥềǦƱậǉ\"ǦǁƐǦƸƽỉǦƸƑƾǦƼƔ?ǦƨƶǦđầǊǦƸƚǦƷƾếǉǦǀƽƇǃƼ?\nƜƾǦđƚ!\nƞƶǄǦǥƽịǃƽ!ǦƞƶǄǦǥƽịǃƽ!",
