    ["累计不肝进度达到10000"] = "ǥƓƸƽǦǁũǓǦǉƾếǃǦđộǦƷấǉǦƸƶǃǦđạǉǦ10000",
    ["完成[春风里·萍水奇缘]"] = "ƣǄƐǃǦǉƽƐǃƽǦ[ƳǊƁǃǦƫƽǄǃƼǦƧƓǦ·ǦƝƔǃƽǦǥƽủǓǦƦỳǦǝǊǓƙǃ]",
    ["【柳岸生灵】丙等解锁"] = "[ƧƾễǊǦƩƼạǃǦƮƾǃƽǦƧƾǃƽ]ǦƨởǦǀƽƚƶǦƽạǃƼǦƝƓǃƽ",
    ["完成[耸翠楼·和味知音]"] = "ƣǄƐǃǦǉƽƐǃƽǦ[ǥủǃƼǦǥƽƕǓǦƧƁǊǦ·ǦƣƛƶǦƱịǦǥǇƾǦƀǂ]",
    ["新白娘子传奇主题套装，限时上架。\n西湖美景三月天，春雨如酒柳如烟。\n惟记青袂挽素练，浮生兰舟泛流年。"] = "ƝộǦǉǇƶǃƼǦǅƽụƸǦƸƽủǦđềǦǥƁǃǦƝạƸƽǦƩươǃƼǦǥửǦǥǇǊǓềǃǦƦỳ,ǦǂởǦƷƑǃǦƼƾớƾǦƽạǃ.\nƞảǃƽǦđẹǅǦǥƁǓǦƣồǦǉƾếǉǦǉƽƑǃƼǦƷƶ,ǦǂưƶǦǍǊƁǃǦǃƽưǦǇượǊǦǁƾễǊǦǃƽưǦǀƽƚƾ.\nƞƽỉǦǃƽớǦǉƶǓǦƑǄǦǍƶǃƽǦǋƑƸǦǁụƶǦǉǇắǃƼ,ǦǅƽƖǦǈƾǃƽǦǉƽǊǓềǃǦǁƶǃǦǉǇƇƾǦǃăǂǦǉƽƑǃƼ.",
    ["恋心暗生，绘影成缘。察心动情动，绘#Y恋慕之缘#E。"] = "ƧƛǃƼǦǓƙǊǦǉƽầǂǦǃảǓǦǈƾǃƽ,ǦǅƽƑƸǦƽƔǃƽǦǉƽƐǃƽǦǤǊǓƙǃ.ǦƮƑǉǦǃƽậǃǦǁƛǃƼǦđộǃƼǦǉƔǃƽǦđộǃƼ,ǦƼƽƾǦǁạƾǦ#YǤǊǓƙǃǦǅƽậǃǦƑƾǦǂộ#E.",
    ["衣缘布挂"] = "ƨƚƸǦǉǇƺǄǦǋảƾǦǤǊǓƙǃǦƑǄ",
    ["青白蛇划船彩蛋"] = "ǥǇứǃƼǦƫƽụƸǦƮƾǃƽǦǥƽƶǃƽǦƝạƸƽǦƳƐǦƸƽƘǄǦǉƽǊǓềǃ",
    ["耸翠楼·和味知音"] = "ǥủǃƼǦǥƽƕǓǦƧƁǊǦ·ǦƣƛƶǦƱịǦǥǇƾǦƀǂ",
    ["半袖春霖半袖青，【青鳞拂雨】轻挽流年，漾开涟漪光影，只等那懂得春雨如酒、柳烟如梦的知音，化作浮生里最动人的一笔丹青。"] = "ƩửƶǦǉƶǓǦƑǄǦǂưƶǦǍǊƁǃǦǃửƶǦǉƶǓǦƑǄǦǍƶǃƽ,Ǧ[ǥƽƶǃƽǦƧƁǃǦƫƽấǉǦƱũ]ǦǀƽẽǦǃƓǊǦƼƾữǦǃăǂǦǉƽƑǃƼ,ǦƼợǃǦǈƚǃƼǦƑǃƽǦǃướƸ,ǦƸƽỉǦđợƾǦǉǇƾǦƁǂǦǉƽấǊǦƽƾểǊǦǂưƶǦǍǊƁǃǦǃƽưǦǇượǊ,ǦǀƽƚƾǦǁƾễǊǦǃƽưǦǂộǃƼǦấǓ,ǦƽƚƶǦǉƽƐǃƽǦǃƗǉǦđƶǃǦǉƽƶǃƽǦǁƶǓǦđộǃƼǦǁƛǃƼǦǃƼườƾǦǃƽấǉǦǉǇǄǃƼǦƸƅƾǦǅƽƖǦǈƾǃƽ.",
    ["全新发型，限时上架。\n青鳞拨水碎寒波，懒闻红尘事几何。\n借来春雨三分醉，且伴轻舟和棹歌。"] = "ƦƾểǊǦǉƚƸǦƽǄƐǃǦǉǄƐǃǦǂớƾ,ǦǂởǦƷƑǃǦƼƾớƾǦƽạǃ.\nƱảǓǦǍƶǃƽǦƼạǉǦǃướƸǦǅƽƑǦǈƚǃƼǦǁạǃƽ,ǦƷƾếǃƼǦǃƼƽƺǦƸƽǊǓệǃǦƽồǃƼǦǉǇầǃǦǂấǓǦƷậǃ.\nƨượǃǦƸƽƕǉǦǂưƶǦǍǊƁǃǦƷƶǦǅƽầǃǦǈƶǓ,ǦƽƃǓǦƸƖǃƼǦǉƽǊǓềǃǦǃƽẹǦƽƛƶǦƷƐƾǦǉǇạǄǦƸƶ.",
    ["白首同舟"] = "ƝạƸƽǦǥƽủǦĐồǃƼǦƞƽƁǊ",
