    ["上课时间……"] = "ƢƾờǦǁƙǃǦǁớǅ...",
    ["枪游龙"] = "ǥƽươǃƼǦǝǊǦƧǄǃƼ",
    ["愁铃客！你给老子等着！老子能从你刀下活一回，就能活第二回！别让老子逮着你——！"] = "ƮầǊǦƧƾǃƽǦƦƽƑƸƽ!ǦƩƼươƾǦđợƾǦđấǓǦƸƽǄǦǁƃǄǦǉử!ǦƧƃǄǦǉửǦƸƚǦǉƽểǦǈốǃƼǦǈƚǉǦǤướƾǦđƶǄǦƸủƶǦǃƼươƾǦǂộǉǦǁầǃ,ǦǉƽƔǦƸƚǦǉƽểǦǈốǃƼǦǈƚǉǦǁầǃǦǉƽứǦƽƶƾ!ǦĐừǃƼǦđểǦǁƃǄǦǉửǦƷắǉǦđượƸǦǃƼươƾǦ——!",
    ["奇术盾"] = "ƦƽƾƙǃǦǀỳǦǉƽǊậǉ",
    ["后经审讯，那门子招供：原是他前些日失手杀了人，将尸首埋于镇北荒郊。"] = "ƮƶǊǦǀƽƾǦǆǊƶǦǉƽẩǂǦǋấǃ,ǦǉƙǃǦƼƑƸǦƸổǃƼǦđƚǦǀƽƶƾǦǃƽậǃ:ǦƣƚƶǦǇƶǦƽắǃǦǂấǓǦƽƇǂǦǉǇướƸǦǉƽấǉǦǉƽủǦƼƾếǉǦǃƼườƾ,ǦƷƇǃǦƸƽƇǃǦǉƽƾǦǉƽểǦởǦǋƖǃƼǦƽǄƶǃƼǦǤƃǦǅƽƓƶǦƷắƸǦǉǇấǃ.",
    ["这便是释迦牟尼像，当真令人心生敬畏。"] = "ĐƁǓǦƸƽƓǃƽǦǁƐǦǉượǃƼǦǥƽƓƸƽǦƞƶǦƨƁǊǦƩƾ,ǦǆǊảǦǉƽựƸǦǀƽƾếǃǦǃƼườƾǦǉƶǦǈƾǃƽǦǁƛǃƼǦǀƓǃƽǦǈợ.",
    ["区域22"] = "ƦƽǊǦǋựƸǦ22",
    ["这水袖，洗得都发白了。哎，这年头，唱戏的也是看人下菜碟，没钱连身好行头都置办不起。"] = "ǥƶǓǦƑǄǦđƐǄǦǀƗǅǦǃƐǓ,ǦƼƾặǉǦđếǃǦǂứƸǦǅƽƶƾǦǉǇắǃƼǦƸảǦǇƶǦǇồƾ.ǦẤǓǦǤƐ,ǦǉƽờƾǦƷǊổƾǦǃƐǓ,ǦǃƼườƾǦǍướǃƼǦƽƑǉǦƸũǃƼǦǅƽảƾǦǃƽƔǃǦǂặǉǦƷắǉǦƽƔǃƽǦǤǄǃƼ,ǦǀƽƇǃƼǦƸƚǦǉƾềǃǦǉƽƔǦǃƼƶǓǦƸảǦǂộǉǦƷộǦǓǦǅƽụƸǦǉửǦǉếǦƸũǃƼǦǀƽƇǃƼǦǈắǂǦǃổƾ.",
    ["珍凝·晶瑚"] = "ǥǇƁǃǦƩƼưǃƼǦ·ǦǥƾǃƽǦƣồ",
    ["雨水么劳劳多，做些热菜暖暖身子好了。"] = "ƨưƶǦƼƾƚǦǁấǉǦǅƽấǉǦǉƽếǦǃƐǓ,ǦǁƐǂǦƸƽƕǉǦǂƚǃǦǃƚǃƼǦƽổƾǦđểǦǁƐǂǦấǂǦǃƼườƾǦǁƐǦđượƸǦǇồƾ.",
    ["今日来了不少生面孔，我就还是给各位介绍两句吧！"] = "ƣƇǂǦǃƶǓǦǉớƾǦđƁǓǦǀƽƇǃƼǦƓǉǦƼươǃƼǦǂặǉǦǁạ,ǦǉƶǦǋẫǃǦǁƐǦǃƙǃǦƼƾớƾǦǉƽƾệǊǦǋớƾǦƸƑƸǦǋịǦǋƐƾǦƸƁǊǦǋậǓ!",
    ["和蒲景庐对话"] = "ǥǇƛǦƸƽǊǓệǃǦǋớƾǦƝồǦƞảǃƽǦƧư",
    ["我就这么干躺着，最后真能拿到赏钱吗？"] = "ǥƶǦƸứǦǃằǂǦǁƔǦǇƶǦǃƽưǦǉƽếǦǃƐǓ,ǦƸǊốƾǦƸƖǃƼǦǉƽựƸǦǈựǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦǉƾềǃǦǉƽưởǃƼǦǈƶǄ?",
    ["江南区域更新"] = "ƞậǅǦǃƽậǉǦǀƽǊǦǋựƸǦƢƾƶǃƼǦƩƶǂ",
    ["在杭州·云家岙拍照"] = "ƞƽụǅǦảǃƽǦǉạƾǦƣƐǃƼǦƞƽƁǊǦ·ǦƱƁǃǦƢƾƶǦỔ",
    ["见闻183"] = "ƦƾếǃǦǋăǃǦ183",
    ["屋里头还有些坯子，等会你就别走了，我回去拿好咯。"] = "ǥǇǄǃƼǦǃƽƐǦǋẫǃǦƸƛǃǦǋƐƾǦǅƽƇƾǦƼốǂ,ǦǁƑǉǦǃữƶǦǃƼươƾǦđừǃƼǦđƾǦǋộƾ,ǦđểǦǉƶǦǆǊƶǓǦǋềǦǁấǓǦƸƽǄǦđƐǃƼǦƽǄƐǃƼ.",
    ["因双刀刀法而留名《藏锋志》者，必有可记之敌。\n三更天门下弟子，深谙双刀之道。刀法迅疾，招式迅猛，缠斗愈久，攻势愈发凶厉。"] = "ƦẻǦǁưǊǦǤƶǃƽǦǈửǦǈƑƸƽ《ǥƐǃƼǦƫƽǄǃƼǦƞƽƓ》ǦǃƽờǦǈǄǃƼǦđƶǄǦǅƽƑǅ,ǦắǉǦƸƚǦǀẻǦđịƸƽǦđƑǃƼǦƼƽƾǦǃƽớ.\nĐệǦǉửǦǂƇǃǦƽạǦ#YǉƶǂǦƞƶǃƽǦǥƽƾƙǃ#E,ǦǉƾǃƽǦǉƽƇǃƼǦđạǄǦǈǄǃƼǦđƶǄ.ǦĐƶǄǦǅƽƑǅǦƸƽớǅǦǃƽǄƑǃƼ,ǦƸƽƾƙǊǦǉƽứƸǦǂƃǃƽǦǁƾệǉ,ǦǆǊấǃǦđấǊǦƸƐǃƼǦǁƁǊ,ǦǉƽếǦƸƇǃƼǦƸƐǃƼǦǉǇởǦǃƙǃǦƽǊǃƼǦƽƃǃ.",
    ["哪能再议？今夜子时，你可一定要记得来文兴斋找我啊！"] = "ƮƶǄǦƸƛǃǦƷƐǃǦǁạƾǦđượƸǦƸƽứ?ǦĐƙǂǦǃƶǓǦƼƾờǦǥƈ,ǦǃƼươƾǦǃƽấǉǦđịǃƽǦǅƽảƾǦǃƽớǦđếǃǦƱăǃǦƣưǃƼǦǥǇƶƾǦǉƔǂǦǉƶǦđấǓǦǃƽƗ!",
    ["怪无常，怪无常，来去如风世事忙。\n步履张狂，且去人间闹一场。"] = "ƬǊƑƾǦǋƇǦǉƽườǃƼ,ǦǆǊƑƾǦǋƇǦǉƽườǃƼ,ǦđếǃǦđƾǦǃƽưǦƼƾƚǦǉƽếǦǈựǦƷậǃǦǇộǃ.\nƝướƸǦƸƽƁǃǦƸǊồǃƼǦǃƼạǄ,ǦƽƃǓǦƸứǦđếǃǦƸƅƾǦǃƽƁǃǦƼƾƶǃǦǁƐǂǦǂộǉǦǉǇậǃǦǉưǃƼǦƷừǃƼ.",
    ["银钱"] = "ƩƼƁǃǦǉƾềǃ",
    ["刘俊"] = "ƧưǊǦǥǊấǃ",
    ["阿弥陀佛，是也，是也……"] = "ƜǦǤƾǦđƐǦƫƽậǉ,ǦǅƽảƾǦǋậǓ,ǦǅƽảƾǦǋậǓ...",
    ["不用了不用了！文元您真是海纳百川、雅量高致！弟子对您的敬仰有如滔滔江水连绵不绝——"] = "ƦƽƇǃƼǦƸầǃǦđƁǊǦǀƽƇǃƼǦƸầǃǦđƁǊ!ǦƱăǃǦƩƼǊǓƙǃǦǃƼƐƾǦđƕǃƼǦǁƐǦƷƾểǃǦǇộǃƼǦǈƇǃƼǦǈƁǊ,ǦǃƽƃǦǁượǃƼǦƸƶǄǦƸƶǄ!ǦƧệǦđệǦǀƓǃƽǦǉǇọǃƼǦǃƼƐƾǦǉựƶǦǃƽưǦǃướƸǦǈƇǃƼǦƸǊồǃǦƸǊộǃǦǀƽƇǃƼǦǤứǉǦ——",
    ["交还书籍"] = "ǥǇảǦǁạƾǦǈƑƸƽ",
    ["陌上烟雨客，拾趣江南行。"] = "ƦƽƑƸƽǦǀƽƚƾǦǂưƶǦǉǇƙǃǦđườǃƼǦǂƛǃ,ǦƽƐǃƽǦǉǇƔǃƽǦǉƽưởǃƼǦǃƼǄạǃǦǉƽƕǦǋǊƾǦƢƾƶǃƼǦƩƶǂ.",
    ["这潭水好清呀，都能照见我的脸！怪不得鱼都养得胖嘟嘟的。"] = "ƱũǃƼǦǃướƸǦǃƐǓǦǉǇǄǃƼǦǆǊƑǦƸơǦƸƽứ,ǦđếǃǦƸảǦǂặǉǦǉƶǦƸũǃƼǦǈǄƾǦǉƽấǓ!ǦƣảǦƸƽƾǦǉǇƑƸƽǦƸƑǦƸǄǃǦǃƐǄǦƸǄǃǦǃấǓǦǃǊƇƾǦđềǊǦǂậǅǦǂƕǅǦǂƓǅ.",
    ["七宝茶者，取茶芽入滚汤为底。复以枣、茱萸、芝麻等七般甘香之物，纳盆中细细碾磨，待磨至细末、香气漫出，乃倾入茶汤。以茶勺调和均匀，七种香物融于茶芽清芬，便成七宝茶。"] = "ǥƽấǉǦƝảǄǦǥǇƐǦǁƐǦǁấǓǦƷƕǅǦǉǇƐǦƸƽǄǦǋƐǄǦǃướƸǦǈƇƾǦǁƐǂǦǃềǃ.ǦƧạƾǦǤƖǃƼǦƸƑƸǦǉƽứǦǃƼọǉǦǉƽơǂǦǃƽưǦǉƑǄ,ǦǉƽƖǦǤǊ,ǦǂƘ...ǦƷảǓǦǋị,ǦƸƽǄǦǋƐǄǦƸốƾǦǍƶǓǦǂịǃǦǂƐǃƼ,ǦđợƾǦǍƶǓǦđếǃǦǀƽƾǦǃƽǊǓễǃǦǂịǃ,ǦƽươǃƼǦǉƽơǂǦǉỏƶǦǇƶ,ǦǂớƾǦđổǦǋƐǄǦǃướƸǦǉǇƐ.ǦǝƖǃƼǦǂǊỗǃƼǦǉǇƐǦǀƽǊấǓǦđềǊǦƸƽǄǦƽƛƶǦǆǊǓệǃ,ǦƷảǓǦǋịǦƽươǃƼǦǁƾệǊǦǆǊǓệǃǦǋƐǄǦƽươǃƼǦǉƽơǂǦǉƽƶǃƽǦǂƑǉǦƸủƶǦƷƕǅǦǉǇƐ,ǦǁƾềǃǦǉƽƐǃƽǦǥƽấǉǦƝảǄǦǥǇƐ.",
    ["《金刚经》……诶，在这儿！"] = "《ƦƾǂǦƞươǃƼǦƦƾǃƽ》...Ǧơ,ǦởǦđƁǓǦǃƐǓ!",
    ["经年旧事（五） "] = "ƞƽǊǓệǃǦƸũǦǃăǂǦǉƽƑǃƼǦ(Ʃăǂ)",
    ["与小沙弥对话"] = "ǥǇƛǦƸƽǊǓệǃǦǋớƾǦǉƾểǊǦǈƶǦǤƾ",
    ["我自己偷偷溜出来的！我可不怕黑，我命硬得很。"] = "ǥƶǦǉựǦǂƔǃƽǦǁƗǃǦǁƕǉǦǉǇốǃǦǇƶǦđấǓ!ǦǥƶǦǀƽƇǃƼǦǈợǦǉǇờƾǦǉốƾǦđƁǊ,ǦǂạǃƼǦǉƶǦƸứǃƼǦǁắǂǦđấǓ.",
    ["舆图、舆图……"] = "ƝảǃǦđồ,ǦƷảǃǦđồ...",
    ["命中累积#Y「醉虾值」#E，叠满后引爆造成一次高额伤害，并提升#Y「醉酒」#E的持续伤害。"] = "ǥƓƸƽǦǁũǓǦ#Y'ƢƾƑǦǉǇịǦǉƇǂǦǈƶǓ'#EǦǀƽƾǦđƑǃƽǦǉǇƕǃƼ,ǦǀƽƾǦƸộǃƼǦǤồǃǦđầǓǦǈẽǦǀƓƸƽǦǃổǦƼƁǓǦǂộǉǦǁầǃǦǈƑǉǦǉƽươǃƼǦǁớǃ,ǦđồǃƼǦǉƽờƾǦƼƾƶǦǉăǃƼǦǈƑǉǦǉƽươǃƼǦǤǊǓǦǉǇƔǦƸủƶǦ#Y'ƮƶǓǦǇượǊ'#E.",
    ["严世昌"] = "ƩƼƽƾƙǂǦǥƽếǦƳươǃƼ",
    ["唐宋越窑制作工艺之一，将已经处理过的精料放置在转盘上，通过转盘转动，用手或工具将泥料塑形成自己心中的形状。"] = "ƨộǉǦǉǇǄǃƼǦǃƽữǃƼǦǀỹǦǉƽǊậǉǦƸƽếǦǉƑƸǦǁƛǦƱƾệǉǦǉƽờƾǦĐườǃƼǦ-ǦǥốǃƼ,ǦđặǉǦǃƼǊǓƙǃǦǁƾệǊǦǉƾǃƽǦƸƽếǦđƃǦǆǊƶǦǍửǦǁƈǦǁƙǃǦƷƐǃǦǍǄƶǓ,ǦǉƽƇǃƼǦǆǊƶǦǈựǦǆǊƶǓǦƸủƶǦƷƐǃǦǍǄƶǓ,ǦǤƖǃƼǦǉƶǓǦƽǄặƸǦǤụǃƼǦƸụǦǉạǄǦƽƔǃƽǦđấǉǦǈƗǉǦǉƽƐǃƽǦƽƔǃƽǦǤạǃƼǦǉǇǄǃƼǦǉƁǂǦǉǇƓǦǂƔǃƽ.",
    ["仙灵所隐"] = "ǥƾƙǃǦǁƾǃƽǦẩǃǦƼƾấǊ",
    ["街坊邻居闻说后议论纷纷，都说是有冤魂来告状了，都提议找早悟寺的师父做场水陆法事。"] = "ƧƑǃƼǦƼƾềǃƼǦǅƽốǦǍƑǦǃƼƽƺǦǍǄǃƼǦǁƾềǃǦƷƐǃǦǉƑǃǦǍƇǃǦǍƶǄ,ǦđềǊǦƷảǄǦǁƐǦƸƚǦǄƶǃǦƽồǃǦđếǃǦƸƑǄǦǉǇạǃƼ,ǦƶƾǦǃấǓǦđềǦǃƼƽịǦǂờƾǦǈưǦǅƽụǦƸƽƖƶǦǥảǄǦƩƼộǦǁƐǂǦǂộǉǦǉǇậǃǦǅƽƑǅǦǈựǦǉƽủǓǦǁụƸ.",
    ["照常练功，但划水摸鱼难以避免"] = "ƧǊǓệǃǦƸƇǃƼǦǃƽưǦǉƽườǃƼǦǁệ,ǦǃƽưǃƼǦǋƾệƸǦǉǇốǃǦǋƾệƸǦƸƁǊǦƼƾờǦǁƐǦǀƽƚǦǉǇƑǃƽǦǀƽỏƾ",
    ["倒影宝箱-江南-花港2"] = "ƭươǃƼǦǅƽảǃǦƸƽƾếǊǦ-ǦƢƾƶǃƼǦƩƶǂǦ-ǦƣǄƶǦƞảǃƼǦ2",
    ["因织幻破法之刃而留名《藏锋志》者，必有可记之敌。\n幻术与重刀，皆是她的武器。柔时困敌于无形，刚时碎铁如枯木。与之对敌，虽为两身，却彼此相知如一珏共振。"] = "ƦẻǦǁưǊǦǤƶǃƽǦǈửǦǈƑƸƽ《ǥƐǃƼǦƫƽǄǃƼǦƞƽƓ》ǦǃƽờǦǁưỡƾǦǤƶǄǦǤệǉǦảǄǦǅƽƑǦǅƽƑǅ,ǦắǉǦƸƚǦǀẻǦđịƸƽǦđƑǃƼǦƼƽƾǦǃƽớ.\nǥƽǊậǉǦảǄǦảǃƽǦǋƐǦǉǇọǃƼǦđƶǄ,ǦđềǊǦǁƐǦǋũǦǀƽƓǦƸủƶǦǃƐǃƼǦấǓ.ǦƧƕƸǦǂềǂǦǃƽốǉǦđịƸƽǦǋƐǄǦǋƇǦƽƔǃƽ,ǦǁƕƸǦƸứǃƼǦđậǅǦǋỡǦǈắǉǦǃƽưǦƼỗǦǂụƸ.ǦĐịƸƽǦǉƽủǦǋớƾǦǃƐǃƼ,ǦǉǊǓǦǁƐǦƽƶƾǦǉƽểǦǍƑƸ,ǦǃƽưǃƼǦǁạƾǦǉƽấǊǦƽƾểǊǦǁẫǃǦǃƽƶǊǦǃƽưǦǃƼọƸǦƸƽǊǃƼǦǂộǉǦǉƾếǃƼǦǋƶǃƼ.",
    ["今年冬日，游侠再来赏花呀！说不定，我也能让牡丹再开一回呢！"] = "ƨƖƶǦđƇǃƼǦǃăǂǦǃƶǓ,ǦǤǊǦƽƾệǅǦƽƃǓǦǁạƾǦđếǃǦǃƼắǂǦƽǄƶǦǃƽƗ!ǦƝƾếǉǦđƁǊ,ǦǉƶǦǁạƾǦƸƚǦǉƽểǦǀƽƾếǃǦƽǄƶǦǂẫǊǦđơǃǦǃởǦǉƽƙǂǦǂộǉǦƷậǃǦǃữƶǦđấǓ!",
    ["竹笋宝箱-青瓶居士1"] = "ƭươǃƼǦǂăǃƼǦǉǇƺǦ-ǦǥƽƶǃƽǦƝƔǃƽǦƞưǦƮĩǦ1",
    ["结局隐藏"] = "ƦếǉǦƸụƸǦẩǃ",
    ["武元说笑了！这更深露重的，哪里来的猫……"] = "ƱƅǦƩƼǊǓƙǃǦǃƚƾǦđƖƶǦǇồƾ!ǦƮươǃƼǦđƙǂǦǤƐǓǦđặƸǦǉƽếǦǃƐǓ,ǦǁƐǂǦƼƔǦƸƚǦƸǄǃǦǂƘǄǦǃƐǄ...",
    ["这位老人家......"] = "ƱịǦǁƃǄǦǃƽƁǃǦƼƾƶǦǃƐǓ......",
    ["谁谁谁谁把它放出来了！！"] = "ĐứƶǦǃƐǄǦđứƶǦǃƐǄǦđứƶǦǃƐǄǦǉƽảǦǃƚǦǇƶǦǉƽếǦƽả!!",
    ["拾取一碗酪浆"] = "ƩƽặǉǦǂộǉǦƷƑǉǦǈữƶǦƸƽǊƶ",
    ["师傅，今朝那道莲子羹是怎么做的？侬教教我！"] = "ƮưǦǅƽụ,ǦǂƚǃǦƸƽƘǦƽạǉǦǈƺǃǦƽƇǂǦǃƶǓǦǁƐǂǦǉƽếǦǃƐǄǦǋậǓ?ǦǥƽầǓǦǤạǓǦƸǄǃǦǋớƾ!",
    ["事业运"] = "ƱậǃǦǂƶǓǦǈựǦǃƼƽƾệǅ",
    ["加上你，九个，没例外。"] = "ǥƓǃƽǦƸảǦǃƼươƾ,ǦƸƽƓǃǦǃƼườƾ,ǦǀƽƇǃƼǦǃƼǄạƾǦǁệ.",
    ["茶村"] = "ǥƽƇǃǦǥǇƐ",
    ["昨日那曲子余音绕梁，今日怎就不来了？知音难觅，知音难觅啊！"] = "ƝảǃǦǀƽƕƸǦǃƼƐǓǦƽƇǂǦǆǊƶǦǤưǦƁǂǦǋươǃƼǦǋấǃ,ǦǈƶǄǦƽƇǂǦǃƶǓǦǁạƾǦǀƽƇǃƼǦđếǃǦǃữƶ?ǦǥǇƾǦƁǂǦǀƽƚǦǉƔǂ,ǦǉǇƾǦƁǂǦǀƽƚǦǉƔǂǦǉƽƶǓ!",
    ["已获取该香客/法器，不可重复购买"] = "ĐƃǦǃƽậǃǦđượƸǦƽươǃƼǦǀƽƑƸƽ/ǅƽƑǅǦǀƽƓǦǃƐǓ,ǦǀƽƇǃƼǦǉƽểǦǂǊƶǦǁạƾ",
    ["落子。生意上的事，钱庄门口问去。"] = "ƣạǦƸờ.ǦƞƽǊǓệǃǦƷǊƇǃǦƷƑǃ,ǦǇƶǦǉǇướƸǦƸửƶǦǉƾệǂǦƸầǂǦđồǦǂƐǦƽỏƾ.",
    ["水缸宝箱-江南野外小屋"] = "ƭươǃƼǦǋạƾǦǃướƸǦ-ǦƞăǃǦǃƽƐǦǃƽỏǦƽǄƶǃƼǦǤƃǦƢƾƶǃƼǦƩƶǂ",
    ["林光摇影翠参差，苔色浮青映日迟。\n位于杉树林的风景胜地，可前往此处记述留影。"] = "ƝƚǃƼǦǇừǃƼǦǁƶǓǦđộǃƼǦƷƾếƸǦǈǄǦǁƺ,ǦǈắƸǦǇƙǊǦǃổƾǦǍƶǃƽǦǅƽảǃǦƸƽƾếǊǦƑǃƽǦǃắǃƼǦǂǊộǃ.\nǥƽắǃƼǦƸảǃƽǦǃằǂǦởǦǇừǃƼǦƸƁǓǦǉƖǃƼ,ǦƸƚǦǉƽểǦǉƾếǃǦđếǃǦđƁǓǦƼƽƾǦƸƽƗǅǦǁưǊǦảǃƽ.",
    ["个刘家老二真是拎不清，一天到晚的，自家地不看，净说些人家的不是！"] = "ƞƑƾǦǉƙǃǦƧưǊǦƼƾƶǦǁƃǄǦǃƽịǦǃƐǓǦǉƽậǉǦǀƽƇǃƼǦǇƅǦǅƽảƾǦǆǊấǓ,ǦǈǊốǉǦǃƼƐǓǦđấǉǦǃƽƐǦǂƔǃƽǦǉƽƔǦǀƽƇǃƼǦǉƽƘǂǦǁƚǦǂặǉǦǃƼƚǦǃƼƐǃƼ,ǦƸƽỉǦǉǄƐǃǦđƾǦǈǄƾǦǂƚƾǦƸƽǊǓệǃǦǃƽƐǦǃƼườƾǦǉƶ!",
    ["因善使偃月刀而留名《藏锋志》者，必有可记之敌。\n大宋军中使偃月刀者，刀法狠辣，素有军中第一刀之名。长刀舞动如青龙出海，劈斩之间势不可挡，沙场之上斩敌无数。"] = "ƫƽƐǂǦǀẻǦǁưǊǦǤƶǃƽǦǉǇǄǃƼǦ《ǥạǃƼǦƫƽǄǃƼǦƞƽƓ》ǦǃƽờǦƼƾỏƾǦǤƖǃƼǦǓểǂǦǃƼǊǓệǉǦđƶǄ,ǦắǉǦǅƽảƾǦƸƚǦđịƸƽǦǉƽủǦđƑǃƼǦǃƽớ.\nƩƼườƾǦǉǇǄǃƼǦǆǊƁǃǦĐạƾǦƮǄǃƼǦǤƖǃƼǦǓểǂǦǃƼǊǓệǉǦđƶǄ,ǦđƶǄǦǅƽƑǅǦǉƐǃǦǃƽẫǃ,ǦǍưƶǦǃƶǓǦǋốǃǦƸƚǦǉƾếǃƼǦǁƐǦđệǦǃƽấǉǦđƶǄǦǉǇǄǃƼǦǆǊƁǃǦǃƼũ.ǦĐƶǄǦǤƐƾǦǂƕƶǦǁƙǃǦǉựƶǦǉƽƶǃƽǦǁǄǃƼǦǍǊấǉǦƽảƾ,ǦǉƽếǦƸƽƗǂǦǉựƶǦǋũǦƷƃǄǦǀƽƇǃƼǦǉƽểǦƸảǃǦǅƽƑ,ǦǉǊǃƼǦƽǄƐǃƽǦǈƶǦǉǇườǃƼǦǉǇảǂǦđịƸƽǦǋƇǦǈố.",
